package vn.covie.inventory.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="inventory_balances") public class InventoryBalanceEntity { @Id @Column(name="location_variant_id") private UUID locationVariantId; @Column(name="stock_on_hand",nullable=false) private long stockOnHand; @Column(name="reserved_quantity",nullable=false) private long reservedQuantity; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Version @Column(nullable=false) private long version; protected InventoryBalanceEntity(){} public static InventoryBalanceEntity zero(UUID id,Instant now){InventoryBalanceEntity b=new InventoryBalanceEntity();b.locationVariantId=id;b.updatedAt=now;return b;} public long availableQuantity(){return stockOnHand-reservedQuantity;} public void adjust(long stockDelta,long reservedDelta,Instant now){long nextStock=Math.addExact(stockOnHand,stockDelta),nextReserved=Math.addExact(reservedQuantity,reservedDelta);if(nextStock<0||nextReserved<0||nextReserved>nextStock)throw new IllegalArgumentException("Inventory invariant violated");stockOnHand=nextStock;reservedQuantity=nextReserved;updatedAt=now;} public UUID getLocationVariantId(){return locationVariantId;} public long getStockOnHand(){return stockOnHand;} public long getReservedQuantity(){return reservedQuantity;} public Instant getUpdatedAt(){return updatedAt;} public long getVersion(){return version;} }
